@Override // com.macrovideo.v380.activities.BaseActivity
protected void doInOnCreateMethod(Bundle bundle, Intent intent) {
    setRootViewPaddingVerticalForAndroid15(((ActivityConfigSelectAlarmAreaBinding) this.binding).getRoot(), true, true);
    GlobalDefines.sIsGoToSetting = true;
    GlobalDefines.sIsGoToAlarmAreaSetting = true;
    setStatusBarColor(R.color.ColorBackInvariant);
    SystemStatusBar.setNavigationBarColor(this, getResources().getColor(R.color.color_invariant_000000));
    ((ActivityConfigSelectAlarmAreaBinding) this.binding).commonTopBar.tvTextCommonTopBar.setText(getString(R.string.str_alarm_area));
    Intent intent2 = getIntent();
    if (intent2 != null) {
        Bundle bundleExtra = intent2.getBundleExtra(Defines.HTTP_RESULT_BUNDLE_KEY);
        if (bundleExtra != null) {
            this.mLoginHandle = (LoginHandle) bundleExtra.getParcelable(KEY_LOGIN_HANDLE);
            this.mDeviceInfo = (DeviceInfo) bundleExtra.getParcelable(KEY_DEVICE_INFO);
            if (this.mLoginHandle != null) {
                LogUtil.d(TAG, "<literal omitted>" + this.mLoginHandle.getNewDeviceType() + "<literal omitted>" + this.mLoginHandle.getVideoSplicing());
                if (GlobalDefines.isDoubleChannelDevice(this.mLoginHandle.getNewDeviceType())) {
                    if (this.mLoginHandle.getVideoSplicing() == 7 || this.mLoginHandle.getVideoSplicing() == 8) {
                        this.mCameraMode = 3;
                    } else {
                        this.mCameraMode = 1;
                    }
                } else if (GlobalDefines.isTripleChannelDevice(this.mLoginHandle.getNewDeviceType())) {
                    this.mCameraMode = 0;
                } else {
                    this.mCameraMode = 0;
                }
                this.mIsDevSpliceDoubleChannel = GlobalDefines.isSpliceDoubleChannelDevice(this.mLoginHandle.getNewDeviceType());
            }
        }
        this.mDeviceID = intent2.getIntExtra("device_id", 0);
        DeviceConfigSettingAlarmSettingFragment.sAlarmAreaColumns = intent2.getIntExtra(KEY_AREA_COLUMNS, 8);
        DeviceConfigSettingAlarmSettingFragment.sAlarmAreaRows = intent2.getIntExtra(KEY_AREA_ROWS, 4);
        LogUtil.i(TAG, "<literal omitted>" + DeviceConfigSettingAlarmSettingFragment.sAlarmAreaColumns);
        LogUtil.i(TAG, "<literal omitted>" + DeviceConfigSettingAlarmSettingFragment.sAlarmAreaRows);
    }
    initPlayer();
    initAlarmAreaView();
    changeSelectBtn();
}
